import{_ as s,c as a,o as p,a0 as l}from"./chunks/framework.CAoHpFZS.js";const u=JSON.parse('{"title":"使用AI数理接口流程提示词","description":"","frontmatter":{},"headers":[],"relativePath":"article/ai/提示词/使用AI数理接口流程提示词.md","filePath":"article/ai/提示词/使用AI数理接口流程提示词.md"}'),e={name:"article/ai/提示词/使用AI数理接口流程提示词.md"};function i(c,n,t,r,o,d){return p(),a("div",null,n[0]||(n[0]=[l(`<h1 id="使用ai数理接口流程提示词" tabindex="-1">使用AI数理接口流程提示词 <a class="header-anchor" href="#使用ai数理接口流程提示词" aria-label="Permalink to &quot;使用AI数理接口流程提示词&quot;">​</a></h1><p>从一个普通开发者的视角及一个团队推动者的视角，浅谈如何将AI真正落地于业务需求开发。</p><blockquote><p><a href="https://mp.weixin.qq.com/s/ANbi9KOjbTdvdTCLC-ENIA" target="_blank" rel="noreferrer">https://mp.weixin.qq.com/s/ANbi9KOjbTdvdTCLC-ENIA</a></p></blockquote><h2 id="背景需求" tabindex="-1">背景需求 <a class="header-anchor" href="#背景需求" aria-label="Permalink to &quot;背景需求&quot;">​</a></h2><p>1.整体业务背景：高德商家平台经营成长业务，包含店铺装修相关功能。B端商家生产内容，如官方相册、品牌故事、特色推荐等模块，作为店铺装修的一部分，提供给C端用户消费。</p><p>2.本期需求背景：需要新增一个“找路指引”模块，商家在B端上传图文视频等模态的内容，指导C端用户如何从附近地标到达店铺，“打通最后100米”。</p><h2 id="技术背景" tabindex="-1">技术背景 <a class="header-anchor" href="#技术背景" aria-label="Permalink to &quot;技术背景&quot;">​</a></h2><p><strong>1.历史技术问题：</strong></p><p>a.数据模型设计过于复杂，且由于命名不规范等导致理解成本过高。</p><p>b.由于数据模型复杂，接口的出入参特别复杂，且存在多级嵌套情况，造成理解维护困难。</p><p>c.内部调用链路过于复杂，存在很多handler分支逻辑，难以梳理调用链路。且应用内历史模块和业务逻辑半数以上不再使用。</p><p><strong>2.整体技术架构：</strong></p><p>a.由于本文主要为了说明Cursor使用，具体店铺装修域的技术架构并非本文重点，不在此详细介绍。读者可以简单理解为将装修内容划分为“内容元素”和“元素与店铺的绑定关系”两个领域实体，围绕这两个领域展开内容相关的增删改、审核、下游交互等一系列链路。</p><p><strong>3.本期技术目标：</strong></p><p>a.由于新增业务模块，故本次同时对历史技术链路进行重构，后续逐步将历史业务模块迁移。</p><p>b.重构目标包括：</p><p>i.简化数据模型，降低理解和维护成本；</p><p>ii.优化接口设计，降低接口复杂度并解决多级嵌套问题；</p><p>iii.清晰调用链路，减少复杂的handler逻辑，提高代码可维护性</p><h2 id="接口逻辑梳理rule" tabindex="-1">接口逻辑梳理RULE <a class="header-anchor" href="#接口逻辑梳理rule" aria-label="Permalink to &quot;接口逻辑梳理RULE&quot;">​</a></h2><p>为了使Cursor的梳理颗粒度、关注点及输出方式等能够达到预期，我们使用Rules规范接口梳理过程：此过程必须人工实现，Cursor无法感知哪些功能是正在使用的，及业务应该以何种角度去梳理整合。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>---description: </span></span>
<span class="line"><span>此规则为分析软件接口提供全面指南，确保充分理解和文档化复杂接口的业务逻辑和技术实现。当开发人员需要理解现有接口、重构接口实现或创建技术文档时应用此规则。它帮助分析人员系统性地探索源代码，从入口到数据库操作全面跟踪调用链，并产出足够详细的流程描述以支持直接开发和重构。该规则适用于微服务、分布式系统和复杂业务场景，特别适合需要深入理解接口工作原理而无需反复查阅源码的情况。</span></span>
<span class="line"><span>globs: </span></span>
<span class="line"><span>alwaysApply: false</span></span>
<span class="line"><span>---</span></span>
<span class="line"><span># 接口逻辑分析与文档生成规则</span></span>
<span class="line"><span>## 关键规则</span></span>
<span class="line"><span>- 分析接口时必须先通过源码搜索工具明确定位入口点，从Controller或HSF入口处入手- 必须完整追踪调用链路，跟踪从入口到持久层及外部系统调用的完整路径</span></span>
<span class="line"><span>- 必须识别并解释所有条件分支和判断逻辑，包括每个分支的触发条件</span></span>
<span class="line"><span>- 必须详细分析接口中的数据校验规则、转换逻辑和持久化操作</span></span>
<span class="line"><span>- 必须识别并解释并发控制机制，如分布式锁、事务等的使用场景和作用范围</span></span>
<span class="line"><span>- 必须分析所有业务规则实现，包括权益/权限检查和特殊业务场景处理</span></span>
<span class="line"><span>- 必须分析配置驱动的处理逻辑和动态加载的处理器链</span></span>
<span class="line"><span>- 必须分析异步处理环节，包括消息发送、事件发布和审核流程- 必须提供按执行顺序的步骤式流程描述，每个步骤包含具体处理逻辑</span></span>
<span class="line"><span>- 必须使用mermaid语法创建详细流程图，展示主流程和所有重要分支</span></span>
<span class="line"><span>- 必须明确标识同步/异步操作，及其触发条件和处理路径</span></span>
<span class="line"><span>- 必须描述数据模型和关键业务实体，包括主要属性和业务含义</span></span>
<span class="line"><span>- 必须提供足够的细节，使开发人员能直接基于分析结果进行开发，无需再次查阅源码</span></span>
<span class="line"><span>## 源码探索方法</span></span>
<span class="line"><span>1. **接口入口确定**   </span></span>
<span class="line"><span>	- 使用文件搜索和代码搜索工具定位接口入口   </span></span>
<span class="line"><span>	- 优先识别Controller类中的目标方法，关注RequestMapping等注解   </span></span>
<span class="line"><span>	- 确认HTTP请求类型、路径和接受的参数格式   </span></span>
<span class="line"><span>	- 如果没有Controller中的目标方法，也可能是HSF调用，可以寻找相关的HsfService</span></span>
<span class="line"><span>2. **调用链路跟踪**   </span></span>
<span class="line"><span>	- 从入口方法开始，逐层跟踪方法调用关系   </span></span>
<span class="line"><span>	- 重点关注Service层的实现类和方法   </span></span>
<span class="line"><span>	- 注意分析AOP切面和拦截器对接口的影响   </span></span>
<span class="line"><span>	- 追踪到最底层的数据库操作和外部系统调用</span></span>
<span class="line"><span>3. **配置分析**   </span></span>
<span class="line"><span>	- 检查application.yml/properties等配置文件   </span></span>
<span class="line"><span>	- 特别关注与目标接口相关的配置项   </span></span>
<span class="line"><span>	- 分析基于配置的条件处理和动态加载逻辑</span></span>
<span class="line"><span>4. **组件与中间件识别**   </span></span>
<span class="line"><span>	- 识别接口涉及的所有服务和组件   </span></span>
<span class="line"><span>	- 确定使用的中间件类型和用途   </span></span>
<span class="line"><span>	- 分析组件之间的交互方式</span></span>
<span class="line"><span>## 输出组织</span></span>
<span class="line"><span>1. **文本流程描述**   </span></span>
<span class="line"><span>	- 提供按执行顺序的步骤式描述   </span></span>
<span class="line"><span>	- 每个步骤包含具体的处理逻辑和条件判断   </span></span>
<span class="line"><span>	- 使用缩进表示逻辑层级关系   </span></span>
<span class="line"><span>	- 明确标识同步/异步操作</span></span>
<span class="line"><span>2. **流程图**  </span></span>
<span class="line"><span>	- 使用mermaid语法创建详细流程图   </span></span>
<span class="line"><span>	- 清晰划分系统和组件边界   </span></span>
<span class="line"><span>	- 整体使用一张图   </span></span>
<span class="line"><span>	- 通过不同线型区分同步和异步流程</span></span>
<span class="line"><span>3. **数据模型**   </span></span>
<span class="line"><span>	- 描述关键业务实体及其关系   </span></span>
<span class="line"><span>	- 列出主要属性及其业务含义   </span></span>
<span class="line"><span>	- 说明表间的关联关系</span></span>
<span class="line"><span>4. **关键代码分析**   </span></span>
<span class="line"><span>	- 重点解释复杂算法和数据处理逻辑   </span></span>
<span class="line"><span>	- 说明特定业务规则的实现方式   </span></span>
<span class="line"><span>	- 分析性能优化手段</span></span>
<span class="line"><span>## 示例</span></span>
<span class="line"><span>&lt;example&gt;</span></span>
<span class="line"><span>用户: 请分析/api/orders/create接口的实现逻辑。</span></span>
<span class="line"><span>AI: 我将对/api/orders/create接口进行全面分析。首先我需要定位入口点并追踪完整调用链路。</span></span>
<span class="line"><span>[使用代码搜索工具定位入口点]</span></span>
<span class="line"><span>找到了入口点: OrderController.createOrder(@RequestBody OrderCreateRequest request)方法。</span></span>
<span class="line"><span>详细分析流程:</span></span>
<span class="line"><span># /api/orders/create接口完整实现分析</span></span>
<span class="line"><span>## 1. 入口处理 </span></span>
<span class="line"><span>- OrderController.createOrder</span></span>
<span class="line"><span>- 接收OrderCreateRequest对象，包含userId, items[], paymentMethod等字段</span></span>
<span class="line"><span>- 数据校验: 检查userId不为空，items不为空且至少有一项，paymentMethod在支持列表内</span></span>
<span class="line"><span>- 创建OrderContext对象，存储请求参数和处理状态</span></span>
<span class="line"><span>- 调用orderService.createOrder(OrderContext)处理业务逻辑</span></span>
<span class="line"><span>## 2. 业务处理 </span></span>
<span class="line"><span>- OrderServiceImpl.createOrder</span></span>
<span class="line"><span>- 分布式锁控制: 加锁key=order:create:{userId}，防止同一用户并发下单</span></span>
<span class="line"><span>- 用户校验: 调用userService.validateUser(userId)验证用户状态和权限</span></span>
<span class="line"><span>- 商品处理:  </span></span>
<span class="line"><span>	- 遍历items列表，调用productService.getProductDetails获取最新价格和库存  </span></span>
<span class="line"><span>	- 检查库存是否充足，不足则抛出InsufficientStockException  </span></span>
<span class="line"><span>	- 计算订单总价并与请求中价格比对，差异超过阈值抛出PriceChangedException</span></span>
<span class="line"><span>- 优惠处理:  </span></span>
<span class="line"><span>	- 如存在优惠券，调用promotionService.applyPromotion计算折扣  </span></span>
<span class="line"><span>	- 根据用户等级应用会员折扣</span></span>
<span class="line"><span>- 支付预处理: </span></span>
<span class="line"><span>	- 创建支付单，调用paymentService.preparePayment </span></span>
<span class="line"><span>    - 获取支付链接或支付参数</span></span>
<span class="line"><span>- 订单创建: </span></span>
<span class="line"><span>	- 生成订单号: 调用idGenerator.generateOrderId()  </span></span>
<span class="line"><span>	- 创建OrderEntity，设置状态为CREATED  </span></span>
<span class="line"><span>	- 调用orderRepository.save(orderEntity)保存订单  </span></span>
<span class="line"><span>	- 创建OrderItemEntity列表并保存</span></span>
<span class="line"><span>- 锁定库存:  </span></span>
<span class="line"><span>	- 调用inventoryService.lockStock(items)锁定库存  </span></span>
<span class="line"><span>	- 设置库存锁定过期时间为30分钟</span></span>
<span class="line"><span>- 发送消息: </span></span>
<span class="line"><span>	- 通过MQ发送ORDER_CREATED事件  </span></span>
<span class="line"><span>	- 事件包含订单基本信息，不包含敏感支付数据- 返回结果:  </span></span>
<span class="line"><span>	- 构建OrderCreateResponse，包含orderId和paymentInfo  </span></span>
<span class="line"><span>	- 解锁分布式锁  </span></span>
<span class="line"><span>	- 返回响应结</span></span>
<span class="line"><span>## 3. 异步处理流程</span></span>
<span class="line"><span>- 库存锁定超时处理:  </span></span>
<span class="line"><span>	- 定时任务每5分钟检查过期库存锁定  </span></span>
<span class="line"><span>	- 对超过30分钟未支付的订单，释放库存锁定  </span></span>
<span class="line"><span>	- 更新订单状态为CANCELLED</span></span>
<span class="line"><span>- 订单创建事件处理:  </span></span>
<span class="line"><span>	- 物流系统订阅ORDER_CREATED事件准备配送信息  </span></span>
<span class="line"><span>	- 数据分析系统订阅事件更新销售统计  </span></span>
<span class="line"><span>	- 用户中心订阅事件更新用户行为画像</span></span>
<span class="line"><span>## 数据操作详情</span></span>
<span class="line"><span>- orders表:  </span></span>
<span class="line"><span>	- 插入新记录: id, user_id, total_amount, status=&#39;CREATED&#39;, created_at, payment_method</span></span>
<span class="line"><span>- order_items表:  </span></span>
<span class="line"><span>	- 批量插入: order_id, product_id, quantity, unit_price, subtotal</span></span>
<span class="line"><span>- inventory_locks表:  </span></span>
<span class="line"><span>	- 批量插入: product_id, quantity, order_id, expire_at=now()+30min</span></span>
<span class="line"><span>## 异常处理</span></span>
<span class="line"><span>	- 库存不足: 返回HTTP 400，错误码10001，提示具体缺货商品</span></span>
<span class="line"><span>	- 价格变动: 返回HTTP 409，错误码10002，提示重新下单</span></span>
<span class="line"><span>	- 用户无效: 返回HTTP 403，错误码10003</span></span>
<span class="line"><span>	- 支付渠道异常: 返回HTTP 503，错误码20001，触发重试机制</span></span>
<span class="line"><span>	- 数据库异常: 回滚事务，返回HTTP 500，记录详细错误日志</span></span>
<span class="line"><span>	[这里还有详细的mermaid流程图和数据模型分析...]</span></span>
<span class="line"><span>&lt;/example&gt;</span></span>
<span class="line"><span>&lt;example type=&quot;invalid&quot;&gt;</span></span>
<span class="line"><span>用户: 分析用户登录接口</span></span>
<span class="line"><span>AI: 用户登录接口的分析:</span></span>
<span class="line"><span>登录接口负责验证用户凭证并返回访问令牌。入口是AuthController中的login方法，该方法:</span></span>
<span class="line"><span>1. 接收用户名和密码</span></span>
<span class="line"><span>2. 验证用户信息</span></span>
<span class="line"><span>3. 创建JWT令牌</span></span>
<span class="line"><span>4. 返回给用户</span></span>
<span class="line"><span>用户提交凭证后，系统会查询数据库验证身份，然后创建一个包含用户ID和角色的令牌。这个分析存在以下问题:</span></span>
<span class="line"><span>- 没有完整跟踪调用链路</span></span>
<span class="line"><span>- 没有分析校验规则和处理逻辑</span></span>
<span class="line"><span>- 没有提供实际的方法名和参数</span></span>
<span class="line"><span>- 没有说明使用了什么组件和中间件</span></span>
<span class="line"><span>- 缺少具体的数据操作说明</span></span>
<span class="line"><span>- 没有分析异常处理路径</span></span>
<span class="line"><span>- 过于简略，无法用于开发</span></span>
<span class="line"><span>- 没有提供流程图</span></span>
<span class="line"><span>&lt;/example&gt;</span></span></code></pre></div><h2 id="技术方案设计" tabindex="-1">技术方案设计 <a class="header-anchor" href="#技术方案设计" aria-label="Permalink to &quot;技术方案设计&quot;">​</a></h2><p><strong>前期准备</strong></p><p>1.明确当前应用的开发规约，并形成Rules用于后续方案设计和代码开发。否则Cursor在开发时会胡乱创建包路径和文件，代码编写也毫无章法，极大增加Review和修改的复杂度和成本。针对本应用生成的Rules如下，其中包含应用框架规范、文件目录规则、命名规则、代码风格规约等，及具体的示例：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span></span></span>
<span class="line"><span>---</span></span>
<span class="line"><span>description:</span></span>
<span class="line"><span>globs: **/*.java</span></span>
<span class="line"><span>alwaysApply: false</span></span>
<span class="line"><span>---</span></span>
<span class="line"><span># mall-pink-dolphin 微服务项目结构规范</span></span>
<span class="line"><span>## 关键规则</span></span>
<span class="line"><span>- **所有代码必须按照模块化架构放置在正确的位置**，详见下方模块职责说明</span></span>
<span class="line"><span>- **枚举和常量优先使用公共模块**:</span></span>
<span class="line"><span>  - 公共枚举必须放在 \`new-b-dolphin-common\` 模块的 \`com.amap.mp.dolphin.common.enums\` 包下</span></span>
<span class="line"><span>  - 公共常量必须放在 \`new-b-dolphin-common\` 模块的 \`com.amap.mp.dolphin.common.constants\` 包下</span></span>
<span class="line"><span>  - 仅当枚举或常量是模块特定的，才可放在对应模块中</span></span>
<span class="line"><span>- **接口定义必须先于实现**，使用接口和实现分离的方式</span></span>
<span class="line"><span>- **严格遵循分层架构，禁止跨层调用**，必须通过合适的接口调用</span></span>
<span class="line"><span>- **数据对象(DO)必须放在正确的位置**，详见下方DO规范说明</span></span>
<span class="line"><span>- **单元测试必须放在mall-pink-dolphin-start模块中**，确保测试环境的一致性</span></span>
<span class="line"><span>- 公用的方法，必须先写interface再写实现。每个interface有Base类实现，每个模块可以在Base类实现的基础上进行自己的override方式</span></span>
<span class="line"><span>## 模块职责</span></span>
<span class="line"><span>### 1. new-b-dolphin-app (业务服务层)</span></span>
<span class="line"><span>- 路径: \`com.amap.mp.dolphin\`</span></span>
<span class="line"><span>- 责任: 实现业务逻辑，业务编排，调用领域层</span></span>
<span class="line"><span>- 包含:</span></span>
<span class="line"><span>  - \`service\`: 核心业务服务接口和实现类</span></span>
<span class="line"><span>  - \`dto\`: 返回值传输对象，及数据结构转换类</span></span>
<span class="line"><span>  - \`executor\`: 入参传输对象，及数据结构转换类</span></span>
<span class="line"><span>### 2. new-b-dolphin-client (客户端层)</span></span>
<span class="line"><span>- 路径: \`com.amap.mp.dolphin\`</span></span>
<span class="line"><span>- 责任: 定义对外暴露的接口和处理外部请求</span></span>
<span class="line"><span>- 包含:</span></span>
<span class="line"><span>  - \`consumer\`: 消息队列消费者客户端实现</span></span>
<span class="line"><span>  - \`controller\`: Web控制器，处理HTTP请求</span></span>
<span class="line"><span>  - \`hsf\`: HSF服务接口定义和实现</span></span>
<span class="line"><span>### 3. new-b-dolphin-domain (领域层)</span></span>
<span class="line"><span>- 路径: \`com.amap.mp.dolphin\`</span></span>
<span class="line"><span>- 责任: 定义领域模型和领域逻辑</span></span>
<span class="line"><span>- 包含:</span></span>
<span class="line"><span>  - \`model\`: 领域模型，封装业务实体和规则</span></span>
<span class="line"><span>  - \`enums\`: 领域特定的枚举类型</span></span>
<span class="line"><span>  - \`transfer\`: 领域对象转换器</span></span>
<span class="line"><span>  - \`domainservice\`: 领域服务，封装特定领域的业务逻辑</span></span>
<span class="line"><span>### 4. new-b-dolphin-infrastructure (基础设施层)</span></span>
<span class="line"><span>- 路径: \`com.amap.mp.dolphin\`</span></span>
<span class="line"><span>- 责任: 实现数据访问、外部服务调用等基础设施</span></span>
<span class="line"><span>- 包含:</span></span>
<span class="line"><span>  - \`mapper\`: MyBatis数据库映射接口</span></span>
<span class="line"><span>  - \`dataobject\`: 数据对象(DO)，用于数据库访问</span></span>
<span class="line"><span>  - \`gatewayimpl\`: 网关接口实现，封装外部服务调用</span></span>
<span class="line"><span>  - \`diamond\`: Diamond配置中心相关实现</span></span>
<span class="line"><span>  - \`config\`: 配置类</span></span>
<span class="line"><span>  - \`acl\`: 防腐层，隔离外部系统变化</span></span>
<span class="line"><span>### 5. new-b-dolphin-common (公共层)</span></span>
<span class="line"><span>- 路径: \`com.amap.mp.dolphin.common\`</span></span>
<span class="line"><span>- 责任: 提供通用工具类、常量、枚举等</span></span>
<span class="line"><span>- 包含:</span></span>
<span class="line"><span>  - \`utils\`: 通用工具类</span></span>
<span class="line"><span>  - \`constants\`: 公共常量（**优先在此定义常量**）</span></span>
<span class="line"><span>  - \`enums\`: 公共枚举（**优先在此定义枚举**）</span></span>
<span class="line"><span>  - \`exception\`: 异常类</span></span>
<span class="line"><span>## 数据对象(DO)规范</span></span>
<span class="line"><span>### DO对象存放位置</span></span>
<span class="line"><span>**关键规则**: 数据对象(DO)必须放在new-b-dolphin-infrastructure模块的dataobject包中，严格遵循以下位置规范：</span></span>
<span class="line"><span>1. **数据访问对象**:</span></span>
<span class="line"><span>   - 位置: \`new-b-dolphin-infrastructure/src/main/java/com/amap/mp/dolphin/dataobject/\`</span></span>
<span class="line"><span>   - 命名规范: 使用业务实体名加DO后缀，如\`OrderDO.java\`</span></span>
<span class="line"><span>   - 使用场景: 用于数据库表映射的对象，通常与数据库表结构一一对应</span></span>
<span class="line"><span>### DO对象编写规范</span></span>
<span class="line"><span>1. **注解规范**:</span></span>
<span class="line"><span>   - 必须使用\`@Data\`或手动实现getter/setter方法</span></span>
<span class="line"><span>   - 推荐使用\`@Builder\`、\`@NoArgsConstructor\`、\`@AllArgsConstructor\`等Lombok注解减少样板代码</span></span>
<span class="line"><span>   - MyBatis映射对象必须添加\`@TableName(&quot;表名&quot;)\`注解</span></span>
<span class="line"><span>2. **属性规范**:</span></span>
<span class="line"><span>   - 必须注释说明每个字段的业务含义</span></span>
<span class="line"><span>   - 字段命名必须使用驼峰式，与数据库字段命名保持对应关系</span></span>
<span class="line"><span>   - 日期类型优先使用\`java.util.Date\`类型</span></span>
<span class="line"><span>3. **类注释规范**:</span></span>
<span class="line"><span>   - 必须包含类级别JavaDoc注释，说明该DO对象的业务用途</span></span>
<span class="line"><span>   - 注释格式必须包含&quot;数据对象&quot;说明和对应的数据表说明</span></span>
<span class="line"><span>### 使用DO对象的代码规范</span></span>
<span class="line"><span>1. **Mapper接口定义**:</span></span>
<span class="line"><span>   - Mapper接口必须指定对应的DO类型</span></span>
<span class="line"><span>   - 示例: \`public interface OrderMapper extends BaseMapper&lt;OrderDO&gt;\`</span></span>
<span class="line"><span>2. **DO对象转换**:</span></span>
<span class="line"><span>   - DO对象到领域对象的转换应在Repository实现类中进行</span></span>
<span class="line"><span>   - 禁止在Service层直接使用DO对象</span></span>
<span class="line"><span>   - 必须通过Repository接口间接访问DO对象</span></span>
<span class="line"><span>## 单元测试结构</span></span>
<span class="line"><span>- 所有单元测试必须在 \`mall-pink-dolphin-start/src/test/java/com/amap/mp/dolohin/newbdolphin/\` 目录下</span></span>
<span class="line"><span>- 测试类命名必须符合被测试类名+Test的格式，如\`OrderServiceTest\`</span></span>
<span class="line"><span>- 测试方法命名应清晰表明测试的功能和预期结果</span></span>
<span class="line"><span>## 开发新功能流程规范</span></span>
<span class="line"><span>1. **定义领域模型**: 在new-b-dolphin-domain中定义领域模型和服务</span></span>
<span class="line"><span>2. **实现数据访问**: 在new-b-dolphin-infrastructure中实现数据对象和数据访问</span></span>
<span class="line"><span>3. **实现业务逻辑**: 在new-b-dolphin-app中实现业务服务</span></span>
<span class="line"><span>4. **实现接口层**: 在new-b-dolphin-client中实现对外接口</span></span>
<span class="line"><span>5. **编写单元测试**: 在mall-pink-dolphin-start中编写单元测试</span></span>
<span class="line"><span>## 枚举和常量规范</span></span>
<span class="line"><span>**关键规则**: 尽可能使用公共枚举和常量，仅当枚举/常量是高度模块特定的才进行本地定义</span></span>
<span class="line"><span>### 枚举定义位置:</span></span>
<span class="line"><span>1. **第一优先级**: \`new-b-dolphin-common.enums\` 包 - 用于跨模块共享的枚举</span></span>
<span class="line"><span>2. **第二优先级**: \`new-b-dolphin-domain.enums\` 包 - 用于领域特定的枚举</span></span>
<span class="line"><span>3. **最后选择**: 模块内部特定包 - 仅用于模块内部使用的枚举</span></span>
<span class="line"><span>### 常量定义位置:</span></span>
<span class="line"><span>1. **第一优先级**: \`new-b-dolphin-common.constants\` 包 - 用于跨模块共享的常量</span></span>
<span class="line"><span>2. **第二优先级**: \`new-b-dolphin-domain.constants\` 包 - 用于领域特定的常量</span></span>
<span class="line"><span>3. **最后选择**: 模块内部特定包 - 仅用于模块内部使用的常量</span></span>
<span class="line"><span>## 示例</span></span>
<span class="line"><span>&lt;example&gt;</span></span>
<span class="line"><span>// 正确地定义枚举和常量</span></span>
<span class="line"><span>// 1. 公共枚举 - 定义在new-b-dolphin-common中</span></span>
<span class="line"><span>package com.amap.mp.dolphin.common.enums;</span></span>
<span class="line"><span>public enum OrderStatus {</span></span>
<span class="line"><span>    CREATED(&quot;已创建&quot;),</span></span>
<span class="line"><span>    PAID(&quot;已支付&quot;),</span></span>
<span class="line"><span>    DELIVERED(&quot;已发货&quot;),</span></span>
<span class="line"><span>    COMPLETED(&quot;已完成&quot;),</span></span>
<span class="line"><span>    CANCELLED(&quot;已取消&quot;);</span></span>
<span class="line"><span>    </span></span>
<span class="line"><span>    private final String desc;</span></span>
<span class="line"><span>    </span></span>
<span class="line"><span>    OrderStatus(String desc) {</span></span>
<span class="line"><span>        this.desc = desc;</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>    </span></span>
<span class="line"><span>    public String getDesc() {</span></span>
<span class="line"><span>        return desc;</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span>// 2. 公共常量 - 定义在new-b-dolphin-common中</span></span>
<span class="line"><span>package com.amap.mp.dolphin.common.constants;</span></span>
<span class="line"><span>public class OrderConstants {</span></span>
<span class="line"><span>    public static final String ORDER_PREFIX = &quot;ORD&quot;;</span></span>
<span class="line"><span>    public static final int DEFAULT_PAGE_SIZE = 20;</span></span>
<span class="line"><span>    public static final long ORDER_EXPIRE_TIME = 30 * 60 * 1000L; // 30分钟</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span>// 3. 正确的接口定义和实现</span></span>
<span class="line"><span>// 接口定义在new-b-dolphin-client</span></span>
<span class="line"><span>package com.amap.mp.dolphin.hsf;</span></span>
<span class="line"><span>public interface OrderService {</span></span>
<span class="line"><span>    ResultDTO&lt;OrderDTO&gt; createOrder(OrderCreateRequest request);</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span>// 实现在new-b-dolphin-app</span></span>
<span class="line"><span>package com.amap.mp.dolphin.service.impl;</span></span>
<span class="line"><span>@Service</span></span>
<span class="line"><span>public class OrderServiceImpl implements OrderService {</span></span>
<span class="line"><span>    @Autowired</span></span>
<span class="line"><span>    private OrderDomainService orderDomainService;</span></span>
<span class="line"><span>    </span></span>
<span class="line"><span>    @Override</span></span>
<span class="line"><span>    public ResultDTO&lt;OrderDTO&gt; createOrder(OrderCreateRequest request) {</span></span>
<span class="line"><span>        try {</span></span>
<span class="line"><span>            OrderModel orderModel = orderDomainService.createOrder(request);</span></span>
<span class="line"><span>            return ResultDTO.success(orderConverter.toDTO(orderModel));</span></span>
<span class="line"><span>        } catch (Exception e) {</span></span>
<span class="line"><span>            return ResultDTO.error(&quot;创建订单失败&quot;);</span></span>
<span class="line"><span>        }</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span>// 4. 正确的DO对象定义</span></span>
<span class="line"><span>// 数据对象 - 定义在infrastructure.dataobject包中</span></span>
<span class="line"><span>package com.amap.mp.dolphin.dataobject;</span></span>
<span class="line"><span>import lombok.Data;</span></span>
<span class="line"><span>import java.util.Date;</span></span>
<span class="line"><span>import com.baomidou.mybatisplus.annotation.TableName;</span></span>
<span class="line"><span>/**</span></span>
<span class="line"><span> * 订单数据对象</span></span>
<span class="line"><span> * 对应表：t_order</span></span>
<span class="line"><span> */</span></span>
<span class="line"><span>@Data</span></span>
<span class="line"><span>@TableName(&quot;t_order&quot;)</span></span>
<span class="line"><span>publicclassOrderDO {</span></span>
<span class="line"><span>    /**</span></span>
<span class="line"><span>     * 主键</span></span>
<span class="line"><span>     */</span></span>
<span class="line"><span>    private Long id;</span></span>
<span class="line"><span>    </span></span>
<span class="line"><span>    /**</span></span>
<span class="line"><span>     * 创建时间</span></span>
<span class="line"><span>     */</span></span>
<span class="line"><span>    private Date gmtCreate;</span></span>
<span class="line"><span>    </span></span>
<span class="line"><span>    /**</span></span>
<span class="line"><span>     * 订单编号</span></span>
<span class="line"><span>     */</span></span>
<span class="line"><span>    private String orderNo;</span></span>
<span class="line"><span>    </span></span>
<span class="line"><span>    /**</span></span>
<span class="line"><span>     * 订单状态</span></span>
<span class="line"><span>     */</span></span>
<span class="line"><span>    private Integer status;</span></span>
<span class="line"><span>    </span></span>
<span class="line"><span>    // 其他属性...</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span>&lt;/example&gt;</span></span>
<span class="line"><span>&lt;example type=&quot;invalid&quot;&gt;</span></span>
<span class="line"><span>// 错误的代码结构示例</span></span>
<span class="line"><span>// 1. 错误：在错误的模块中定义枚举</span></span>
<span class="line"><span>package com.amap.mp.dolphin.service.enums;  // 错误：应该放在common.enums包下</span></span>
<span class="line"><span>publicenumPaymentType {  // 这是一个应该在公共模块的枚举</span></span>
<span class="line"><span>    ALIPAY, WECHAT, CREDIT_CARD, CASH;</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span>// 2. 错误：跨层调用</span></span>
<span class="line"><span>package com.amap.mp.dolphin.service;</span></span>
<span class="line"><span>@Service</span></span>
<span class="line"><span>publicclassOrderServiceImplimplementsOrderService {</span></span>
<span class="line"><span>    @Autowired</span></span>
<span class="line"><span>    private OrderMapper orderMapper;  // 错误：直接调用基础设施层，应该通过repository接口</span></span>
<span class="line"><span>    </span></span>
<span class="line"><span>    @Override</span></span>
<span class="line"><span>    public OrderDTO createOrder(OrderCreateRequest request){</span></span>
<span class="line"><span>        OrderDO orderDO = new OrderDO();</span></span>
<span class="line"><span>        // 设置DO属性...</span></span>
<span class="line"><span>        orderMapper.insert(orderDO);  // 错误的直接调用</span></span>
<span class="line"><span>        return convert(orderDO);</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span>// 3. 错误：DO对象放在错误的位置</span></span>
<span class="line"><span>package com.amap.mp.dolphin.model;  // 错误：DO应该放在infrastructure.dataobject包中</span></span>
<span class="line"><span>import lombok.Data;</span></span>
<span class="line"><span>/**</span></span>
<span class="line"><span> * 订单数据对象</span></span>
<span class="line"><span> */</span></span>
<span class="line"><span>@Data</span></span>
<span class="line"><span>publicclassOrderDO {  // 错误：应该放在infrastructure.dataobject包中</span></span>
<span class="line"><span>    private Long id;</span></span>
<span class="line"><span>    private String orderNo;</span></span>
<span class="line"><span>    // 其他属性...</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span>// 4. 错误：使用未经转换的DO对象返回给外部</span></span>
<span class="line"><span>package com.amap.mp.dolphin.controller;</span></span>
<span class="line"><span>@RestController</span></span>
<span class="line"><span>publicclassOrderController {</span></span>
<span class="line"><span>    @Autowired</span></span>
<span class="line"><span>    private OrderService orderService;</span></span>
<span class="line"><span>    </span></span>
<span class="line"><span>    @GetMapping(&quot;/orders/{id}&quot;)</span></span>
<span class="line"><span>    public OrderDO getOrder(@PathVariable Long id){  // 错误：直接返回DO对象</span></span>
<span class="line"><span>        return orderService.getOrderDO(id);  // 错误：应该转换为DTO再返回</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span>&lt;/example&gt;</span></span></code></pre></div><h3 id="概要设计" tabindex="-1">概要设计 <a class="header-anchor" href="#概要设计" aria-label="Permalink to &quot;概要设计&quot;">​</a></h3><p>人类开发者在开发代码之前，需要对需求文档进行理解转化，并对应当前应用已有的实现现状，明确需要新增和修改的部分，之后再进行具体代码开发。而Cursor在开发之前，并不一定能完全理解需求文档的意图，转化成预期的技术方案。这依赖于其一是需求的复杂程度，其二是当前应用的知识背景是否全面充足。</p><p>所以为了提高准确性，引入了概要设计的环节，由人类帮助Cursor完成上述步骤，并直接让Cursor根据人类的概要技术方案，产出详细的代码实现设计。这里将概要设计的重点部分展示如下：</p><h3 id="详细设计" tabindex="-1">详细设计 <a class="header-anchor" href="#详细设计" aria-label="Permalink to &quot;详细设计&quot;">​</a></h3><p>概要设计是人类编写的，精确到了接口、数据结构、业务流程层面。但对于让Cursor开发复杂类型需求还不够具体，故需要Cursor生成详细设计，精确到每一层的方法、出入参、伪代码层面，对抗Cursor的不确定性。本文摘录当时部分详细设计展示如下：</p>`,31)]))}const h=s(e,[["render",i]]);export{u as __pageData,h as default};
